package encoding

import (
	"bytes"
	"flag"
	"fmt"
	"go/format"
	"os"
	"slices"
	"testing"
	"unicode/utf8"
)

var update = flag.Bool("update", false, "write tables.go from the character maps in charmap_source_test.go")

type builtin struct {
	name      string
	source    func() *Charmap
	generated *Charmap
}

func builtins() []builtin {
	return []builtin{
		{name: "ascii", source: asciiSource, generated: &asciiCharmap},
		{name: "latin1", source: latin1Source, generated: &latin1Charmap},
		{name: "latin5", source: latin5Source, generated: &latin5Charmap},
		{name: "ebcdic", source: ebcdicSource, generated: &ebcdicCharmap},
	}
}

// generateTables is tables.go: each built-in character map initialized by upstream's
// own algorithm, from upstream's own maps, and written out as data the linker lays
// down -- so the tables are upstream's tables, and none of them is built at run time.
func generateTables(t *testing.T) []byte {
	t.Helper()
	var out bytes.Buffer
	out.WriteString("// Code generated by `go test -update` from charmap_source_test.go; DO NOT EDIT.\n\n")
	out.WriteString("// Added for nemosh: upstream built these in each character set's init. See README.md.\n\n")
	out.WriteString("package encoding\n")
	for _, b := range builtins() {
		source := b.source()
		source.initialize()
		fmt.Fprintf(&out, "\nvar %sCharmap = Charmap{\n\tReplacementChar: 0x%02x,\n\trunes: [256][]byte{\n", b.name, source.ReplacementChar)
		for i, utf := range source.runes {
			out.WriteString("{")
			for j, c := range utf {
				if j > 0 {
					out.WriteString(", ")
				}
				fmt.Fprintf(&out, "0x%02x", c)
			}
			out.WriteString("},")
			if i%8 == 7 {
				out.WriteString("\n")
			} else {
				out.WriteString(" ")
			}
		}
		out.WriteString("},\n\tencodes: []runeByte{\n")
		runes := make([]rune, 0, len(source.bytes))
		for r := range source.bytes {
			runes = append(runes, r)
		}
		slices.Sort(runes)
		for i, r := range runes {
			fmt.Fprintf(&out, "{0x%04x, 0x%02x},", r, source.bytes[r])
			if i%6 == 5 || i == len(runes)-1 {
				out.WriteString("\n")
			} else {
				out.WriteString(" ")
			}
		}
		out.WriteString("},\n}\n")
	}
	formatted, err := format.Source(out.Bytes())
	if err != nil {
		t.Fatalf("the generated tables do not parse: %v", err)
	}
	return formatted
}

func TestTables_areWhatTheSourceMapsGenerate(t *testing.T) {
	// Given
	generated := generateTables(t)
	if *update {
		if err := os.WriteFile("tables.go", generated, 0o644); err != nil {
			t.Fatal(err)
		}
		return
	}

	// When
	current, err := os.ReadFile("tables.go")
	if err != nil {
		t.Fatal(err)
	}

	// Then: a checkout may have turned the line endings into CRLF, and nothing else
	if !bytes.Equal(bytes.ReplaceAll(current, []byte("\r\n"), []byte("\n")), generated) {
		t.Fatal("tables.go is not what charmap_source_test.go generates; run go test -update")
	}
}

// The generated tables are only right if they answer as upstream's do, for every byte
// and for every rune there is.
func TestTables_answerAsUpstreamsAlgorithmDoes(t *testing.T) {
	for _, b := range builtins() {
		t.Run(b.name, func(t *testing.T) {
			// Given
			source := b.source()
			source.Init()
			generated := b.generated.NewEncoder().Transformer.(*cmapEncoder)
			upstream := source.NewEncoder().Transformer.(*cmapEncoder)

			// Then
			if b.generated.ReplacementChar != source.ReplacementChar {
				t.Fatalf("replacement 0x%02x, want 0x%02x", b.generated.ReplacementChar, source.ReplacementChar)
			}
			for i := range 256 {
				if !bytes.Equal(b.generated.runes[i], source.runes[i]) {
					t.Fatalf("byte 0x%02x decodes to % x, want % x", i, b.generated.runes[i], source.runes[i])
				}
			}
			for r := rune(0); r <= utf8.MaxRune; r++ {
				got, gotOK := generated.encode(r)
				want, wantOK := upstream.encode(r)
				if got != want || gotOK != wantOK {
					t.Fatalf("rune %U encodes to (0x%02x, %v), want (0x%02x, %v)", r, got, gotOK, want, wantOK)
				}
			}
		})
	}
}

// What the generated tables are for: a built-in character set is ready without Init
// building anything, and Init leaves it alone.
func TestTables_needNoInitialization(t *testing.T) {
	for _, b := range builtins() {
		// When
		allocations := testing.AllocsPerRun(10, b.generated.Init)

		// Then
		if allocations != 0 || b.generated.bytes != nil {
			t.Fatalf("%s: Init allocated %v times and built a map: %v", b.name, allocations, b.generated.bytes != nil)
		}
	}
}
